#include "hybrid_wavetable_pro.h"
#include <stddef.h>
#define PRESET_MAGIC 0x48575031u
static uint32_t crc32_bytes(const uint8_t *p,uint32_t n){uint32_t c=0xffffffffu,i;uint8_t b;while(n--){c^=*p++;for(i=0;i<8;i++){b=(uint8_t)(c&1u);c=(c>>1)^(0xedb88320u&(0u-(uint32_t)b));}}return ~c;}
static int16_t clamp_s16(int32_t x){return (int16_t)(x>32767?32767:(x< -32768?-32768:x));}
int hybrid_wavetable_import(hybrid_wavetable_t*s,uint8_t slot,const int16_t*pcm,uint16_t count){uint32_t i,idx,frac;uint64_t pos;int32_t a,b;if(!s||!pcm||slot>=4u||count<2u)return -1;for(i=0;i<64u;i++){pos=((uint64_t)i*(uint32_t)(count-1u)*65536u)/63u;idx=(uint32_t)(pos>>16);frac=(uint32_t)(pos&65535u);if(idx>=((uint32_t)count-1u)){idx=(uint32_t)count-2u;frac=65536u;}a=pcm[idx];b=pcm[idx+1u];s->custom_wave[slot][i]=clamp_s16(a+(int32_t)(((int64_t)(b-a)*frac)>>16));}s->custom_valid_mask|=(uint8_t)(1u<<slot);return 0;}
int hybrid_wavetable_clear_custom(hybrid_wavetable_t*s,uint8_t slot){if(!s||slot>=4u)return -1;s->custom_valid_mask&=(uint8_t)~(1u<<slot);return 0;}
int32_t hybrid_wavetable_custom_sample(const hybrid_wavetable_t*s,uint8_t slot,uint32_t phase){uint32_t ix,frac;int32_t a,b;if(!s||slot>=4u||!(s->custom_valid_mask&(1u<<slot)))return 0;ix=phase>>26;frac=(phase>>10)&65535u;a=s->custom_wave[slot][ix];b=s->custom_wave[slot][(ix+1u)&63u];return a+(int32_t)(((int64_t)(b-a)*frac)>>16);}
int32_t hybrid_wavetable_sub_sample(uint32_t phase,uint8_t divider){if(divider<1u)divider=1u;if(divider>4u)divider=4u;phase>>=divider;return (phase&0x80000000u)?-32767:32767;}
int32_t hybrid_wavetable_noise_sample(uint32_t*seed){uint32_t x;if(!seed)return 0;x=*seed?*seed:0x6d2b79f5u;x^=x<<13;x^=x>>17;x^=x<<5;*seed=x;return (int32_t)(x>>16)-32768;}
uint8_t hybrid_wavetable_unison_count(uint8_t n){return n<1u?1u:(n>4u?4u:n);}
void hybrid_wavetable_mod_evaluate(const hybrid_wt_mod_route_t r[HYBRID_WT_MOD_SLOTS],int16_t lfo,uint8_t vel,uint8_t note,int16_t env,hybrid_wt_mod_values_t*out){uint8_t i;int32_t src,v;if(!out)return;out->pitch_q15=out->cutoff_q15=out->osc_mix_q15=out->amp_q15=0;if(!r)return;for(i=0;i<4u;i++){switch(r[i].source){case HYBRID_WT_MOD_LFO:src=lfo;break;case HYBRID_WT_MOD_VELOCITY:src=((int32_t)vel*32767)/127;break;case HYBRID_WT_MOD_KEY:src=((int32_t)note*32767)/127;break;case HYBRID_WT_MOD_ENVELOPE:src=env;break;default:src=0;break;}v=(src*(int32_t)r[i].depth_q15)>>15;switch(r[i].destination){case HYBRID_WT_DEST_PITCH:out->pitch_q15=clamp_s16(out->pitch_q15+v);break;case HYBRID_WT_DEST_CUTOFF:out->cutoff_q15=clamp_s16(out->cutoff_q15+v);break;case HYBRID_WT_DEST_OSC_MIX:out->osc_mix_q15=clamp_s16(out->osc_mix_q15+v);break;case HYBRID_WT_DEST_AMP:out->amp_q15=clamp_s16(out->amp_q15+v);break;default:break;}}}
int hybrid_wavetable_preset_save(const hybrid_wavetable_t*s,const hybrid_wt_mod_route_t r[HYBRID_WT_MOD_SLOTS],hybrid_wt_preset_t*out){uint32_t i;if(!s||!out)return -1;{uint8_t*z=(uint8_t*)out;uint32_t n;for(n=0;n<sizeof(*out);n++)z[n]=0;}out->magic=PRESET_MAGIC;out->version=HYBRID_WT_PRESET_VERSION;out->size=(uint16_t)sizeof(*out);out->wave_a=s->wave_a;out->wave_b=s->wave_b;out->unison_voices=hybrid_wavetable_unison_count(s->unison);out->sub_level=s->sub_level;out->noise_level=s->noise_level;out->custom_valid_mask=s->custom_valid_mask;out->osc2_mix=s->osc2_mix;out->attack=s->attack;out->decay=s->decay;out->sustain=s->sustain;out->release=s->release;out->cutoff=s->cutoff;out->resonance=s->resonance;out->unison_detune=s->unison_detune;for(i=0;i<4u;i++){uint32_t j;for(j=0;j<64u;j++)out->custom[i][j]=s->custom_wave[i][j];if(r)out->modulation[i]=r[i];else{out->modulation[i].source=s->mod_source[i];out->modulation[i].destination=s->mod_destination[i];out->modulation[i].depth_q15=s->mod_depth_q15[i];}}out->crc32=0;out->crc32=crc32_bytes((const uint8_t*)out,(uint32_t)offsetof(hybrid_wt_preset_t,crc32));return 0;}
int hybrid_wavetable_preset_load(hybrid_wavetable_t*s,hybrid_wt_mod_route_t r[HYBRID_WT_MOD_SLOTS],const hybrid_wt_preset_t*p){uint32_t i;if(!s||!p||p->magic!=PRESET_MAGIC||p->version!=HYBRID_WT_PRESET_VERSION||p->size!=sizeof(*p)||p->crc32!=crc32_bytes((const uint8_t*)p,(uint32_t)offsetof(hybrid_wt_preset_t,crc32)))return -1;s->wave_a=p->wave_a;s->wave_b=p->wave_b;s->unison=hybrid_wavetable_unison_count(p->unison_voices);s->sub_level=p->sub_level;s->noise_level=p->noise_level;s->custom_valid_mask=p->custom_valid_mask;s->osc2_mix=p->osc2_mix;s->attack=p->attack;s->decay=p->decay;s->sustain=p->sustain;s->release=p->release;s->cutoff=p->cutoff;s->resonance=p->resonance;s->unison_detune=(uint16_t)(p->unison_detune>5000u?5000u:p->unison_detune);for(i=0;i<4u;i++){uint32_t j;for(j=0;j<64u;j++)s->custom_wave[i][j]=p->custom[i][j];if(r)r[i]=p->modulation[i];s->mod_source[i]=p->modulation[i].source;s->mod_destination[i]=p->modulation[i].destination;s->mod_depth_q15[i]=p->modulation[i].depth_q15;}return 0;}
